<script setup lang="ts">
import { computed } from 'vue';import TopBar from '@/components/ui/TopBar.vue';import Avatar from '@/components/ui/Avatar.vue';import Icon from '@/components/ui/Icon.vue';import { useSessionStore } from '@/stores/session';
const s=useSessionStore();const score=computed(()=>Math.min(99,70+s.stats.myEvents*4+s.stats.pendingRequests));async function edit(){if(!s.user)return;const name=prompt('Имя в V I B E:',s.user.name);if(name===null)return;const bio=prompt('О себе:',s.user.bio||'');if(bio===null)return;await s.updateProfile({name,bio,birthDate:s.user.birthDate})}
</script>
<template><section class="screen"><TopBar/><div v-if="s.user" class="profile"><Avatar :name="s.user.name" :src="s.user.avatarUrl" size="lg"/><h1>{{s.user.name}}</h1><p>{{s.user.username?'@'+s.user.username:'Минск'}} · ★ {{s.user.rating}}</p><div class="pass"><small>V I B E PASS</small><b>{{score}}</b><span>городской рейтинг</span></div><div class="profile-card"><div class="row-between"><h2>О себе</h2><button @click="edit">Изменить</button></div><p>{{s.user.bio||'Расскажите о себе — организаторам проще принимать живые профили.'}}</p></div><div class="menu"><RouterLink to="/my-events"><Icon name="spark"/><div><b>Мои события</b><small>управление и гости</small></div><Icon name="arrow"/></RouterLink><RouterLink to="/inbox"><Icon name="inbox"/><div><b>Заявки и чаты</b><small>{{s.stats.pendingRequests}} ждут решения</small></div><Icon name="arrow"/></RouterLink></div></div><div v-else class="auth-banner"><b>Профиль доступен в Telegram</b><span>{{s.authError}}</span></div></section></template>
